// Smoke test: verifica que require('@healthradar/core') funciona
// dentro del contenedor n8n. Si este nodo falla, el require está
// roto y ningún workflow de producción debe desplegarse.

const core = require('@healthradar/core');

return [{
  json: {
    status: 'ok',
    version: core.version(),
    modules_loaded: [
      typeof core.detectarPeriodo === 'function' ? 'detectarPeriodo' : null,
      typeof core.detectarDepartamento === 'function' ? 'detectarDepartamento' : null,
      typeof core.detectarEnfermedad === 'function' ? 'detectarEnfermedad' : null,
      typeof core.decidirPrediccion === 'function' ? 'decidirPrediccion' : null,
      typeof core.filtrarBoletines === 'function' ? 'filtrarBoletines' : null,
      typeof core.filtrarClima === 'function' ? 'filtrarClima' : null,
      typeof core.construirContextoPrompt === 'function' ? 'construirContextoPrompt' : null,
      typeof core.armarTextoTendencia === 'function' ? 'armarTextoTendencia' : null,
      typeof core.extraerNivelRiesgo === 'function' ? 'extraerNivelRiesgo' : null,
      typeof core.validarResumenBoletin === 'function' ? 'validarResumenBoletin' : null
    ].filter(Boolean)
  }
}];
